/**
 * Practice questions and concept pages for /practice (Lectures 1–4).
 *
 * Both JSON files are generated by scripts/practice/build.py, which runs every
 * question and example in Python before writing them. Edit the Python sources
 * in scripts/practice/, never the JSON.
 */
import questionsJson from './questions.json'
import conceptsJson from './concepts.json'

export type Level = 'easy' | 'intermediate' | 'advanced'

export interface PracticeQuestion {
  id: string
  level: Level
  section: SectionSlug
  prompt: string
  code?: string
  options: string[]
  answer: number
  explanation: string
  /** What "Try it yourself" opens with: the code, with any gap filled in. */
  tryCode?: string
}

export interface ConceptBlock {
  heading: string
  body: string
  code: string | null
  output?: string
}

export interface Concept {
  slug: SectionSlug
  title: string
  lecture: string
  summary: string
  slides: { lecture: number; title: string }[]
  notebook: string
  advanced: string | null
  basics: ConceptBlock[]
  further: ConceptBlock[]
}

export const SECTIONS = [
  { slug: 'variables', label: 'Variables & printing', lecture: 1 },
  { slug: 'types', label: 'Data types', lecture: 1 },
  { slug: 'operators', label: 'Operators & logic', lecture: 1 },
  { slug: 'lists', label: 'Lists', lecture: 2 },
  { slug: 'strings', label: 'Strings', lecture: 2 },
  { slug: 'dictionaries', label: 'Dictionaries', lecture: 2 },
  { slug: 'loops', label: 'Loops', lecture: 3 },
  { slug: 'conditionals', label: 'Conditionals', lecture: 3 },
  { slug: 'functions', label: 'Functions', lecture: 4 },
  { slug: 'errors', label: 'Errors', lecture: 4 },
] as const

export type SectionSlug = (typeof SECTIONS)[number]['slug']

export const LEVELS: { id: Level; label: string; blurb: string }[] = [
  { id: 'easy', label: 'Easy', blurb: 'One idea at a time, straight from the lectures.' },
  { id: 'intermediate', label: 'Intermediate', blurb: 'Ideas combined, and the classic traps.' },
  { id: 'advanced', label: 'Advanced', blurb: 'Including the advanced notebooks — comprehensions, copies, while, try/else/finally.' },
]

export const QUESTIONS = questionsJson as PracticeQuestion[]
export const CONCEPTS = conceptsJson as Concept[]

export const sectionLabel = (slug: string) => SECTIONS.find((s) => s.slug === slug)?.label ?? slug
export const getConcept = (slug: string) => CONCEPTS.find((c) => c.slug === slug)

const COLAB = 'https://colab.research.google.com/github/HocheggerLab/y3-bio-python/blob/main'
export const notebookUrl = (path: string) => `${COLAB}/${path}`
/** "lab02/05_dictionaries_basics.ipynb" → "Lab 2 · dictionaries basics" */
export const notebookLabel = (path: string) => {
  const [lab, file] = path.split('/')
  const name = file.replace(/^\d+_/, '').replace('.ipynb', '').replace(/_/g, ' ').replace('advanced concepts', 'advanced')
  return `Lab ${Number(lab.replace('lab', ''))} · ${name}`
}
